/* Shared accepted progress markup. No data aggregation, graph or layout calls. */
(function(g){
'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function bar(s){if(!s.eligible)return'';return`<div class="progress-bar" role="img" aria-label="${s.learned} learned, ${s.notLearned} explicitly not learned, ${s.unknown} unknown, of ${s.eligible}">${[['learned',s.learned],['not-learned',s.notLearned],['unknown',s.unknown]].map(([name,count])=>`<span class="${name}" style="width:${100*count/s.eligible}%"></span>`).join('')}</div>`;}
const observed=s=>`<p class="progress-date">Last observed (personal): ${s.lastObserved?`<time title="${esc(s.lastObserved)}" datetime="${esc(s.lastObserved)}">${esc(s.lastObserved.slice(0,10))}</time>`:'No personal evidence'}</p>`;
function official(s){return `<p class="official-course-progress">Officially observed Course progress: ${s.state==='UNKNOWN'?'UNKNOWN · No complete personal Course snapshot':`${s.learned} / ${s.eligible} evidenced learned in complete Course snapshot`}</p>${s.lastObserved?observed(s):''}`;}
function card(title,s,denominator,{requirements=false,status=null,officialProgress=null,completionContext=''}={}){
 let body=s.state==='UNKNOWN'?'<strong>Requirements not established</strong><p>UNKNOWN denominator · no progress denominator.</p>':s.eligible===0?`<strong>${requirements?'No requirement Topics':'No eligible Topics'}</strong>`:`<strong>${s.learned} / ${s.eligible} evidenced learned</strong>${bar(s)}<p>${s.learned} learned · ${s.verified} verified<br>${s.notLearned} explicitly not learned · ${s.unknown} unknown<br>${s.remaining} Not yet evidenced learned<br>${s.verifiedUnknown} verification state unknown</p>${s.allLearned?`<p>All eligible Topics evidenced learned${completionContext?' within '+esc(completionContext):''}.</p>`:''}${s.allVerified?'<p>All eligible Topics explicitly verified.</p>':''}`;
 if(officialProgress)body+=official(officialProgress);
 if(requirements)body+=`<p>Personal status: ${status?.status?esc(status.status):'Not recorded'}${status?.lastObserved?` · ${esc(status.lastObserved.slice(0,10))}`:''}</p>`;
 return`<section class="progress-card"><h3>${esc(title)}</h3>${body}<p class="progress-note">Denominator: ${esc(denominator)}</p>${observed(s)}</section>`;
}
function scope(a,row){const type=row.scope_type,id=row.scope_id,label=type[0].toUpperCase()+type.slice(1)+' '+id,course=type==='course';
 return `<section class="category-progress scope-progress">${card(`${label} · ${course?'Global knowledge coverage':'knowledge coverage'}`,a.scope(type,id),course?'All distinct explicitly evidenced Course Topic IDs':type==='stage'?'Explicit Stage-local requirement Topics':'Distinct explicit Project study-plan requirement Topics',{requirements:!course,status:course?null:a.personalStatus(type,id),officialProgress:course?a.officialCourseProgress(id):null})}<p class="progress-note">${course?'Shared Global Topic evidence can originate in another Course. Official Course progress is separate.':'Knowledge coverage does not establish completion, application or readiness.'} Historical local evidence; not live.</p></section>`;
}
function category(a,id,context=null){
 const label=context?`${context.scope_type[0].toUpperCase()+context.scope_type.slice(1)} ${context.scope_id}`:null;
 const kids=[...(a.children.get(id)||[])].filter(child=>a.categories.has(child));
 return`<section class="category-progress"><h3>Contextual knowledge progress</h3>${card('Global Category',a.category(id),'All Global structural descendant Topic IDs, including secondary memberships',{completionContext:'Global Category'})}${context?card(`Active Scope Category · ${label}`,a.categoryInScope(id,context.scope_type,context.scope_id),'Global descendants ∩ active Scope explicit Topic IDs',{completionContext:label}):''}<details open class="subcategory-breakdown"><summary>Immediate child Categories · ${label?'within '+label:'Global'}</summary><p class="progress-note">Distinct totals per child; overlapping memberships mean rows must not be added together.</p>${kids.map(child=>{const s=context?a.categoryInScope(child,context.scope_type,context.scope_id):a.category(child);return`<div class="child-progress"><button data-progress-category="${child}">${esc(a.categories.get(child).title)}</button><p>${s.state==='UNKNOWN'?'Requirements not established':s.eligible===0?'No eligible Topics':`${s.learned} / ${s.eligible} learned · ${s.verified} verified${s.unknown?` · ${s.unknown} unknown`:''}`}</p>${bar(s)}</div>`;}).join('')||'<p>No child Categories.</p>'}</details><p><a href="global.html?key=category%3A${id}">Show Category in Global Atlas ↗</a></p><p class="progress-note">Evidence coverage is not platform-issued Category mastery.</p></section>`;
}
function topic(a,id){const s=a.topic(id),value=(v,yes,no)=>v===true?yes:v===false?no:'Unknown';return`<section class="topic-progress"><p id="personal-status">Learning: ${value(s.learned,'● Learned','○ Explicitly not learned')}<br>Verification: ${value(s.verified,'◎ Verified','Explicitly not verified')}<br>Verification / evaluation state: ${s.verificationStatuses.map(esc).join(', ')||'Unknown'}</p>${observed(s)}<p>Learning source: ${esc(s.evidenceSource||"No learned evidence")}</p>${s.learningEvidence.map(e=>`<p>${esc(e.project_id?"Completed Project "+e.project_id+" · ":"")}${esc(e.source)} · ${esc(e.observed_at||"Date unknown")}${e.is_learned===false?" · observed not learned":""}</p>`).join('')}<p class="progress-note">Owner-attested completed Projects establish learning of their explicit requirement Topics. Verification is independent.</p></section>`;}
const api={bar,observed,official,card,scope,category,topic};g.ProgressPresentation=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
